import{useEffect,useMemo,useRef,useState}from'react'
import{Link,useNavigate,useParams}from'react-router'
import{ArrowDown,ArrowRight,ArrowUp,Camera,CheckCircle2,GripVertical,ImagePlus,Play,RotateCcw,Send,Tag,Trash2}from'lucide-react'
import{CameraCapture}from'@components/ui'
import{useCompleteComplaintAssignmentTicket,useComplaintItemsMedia,useManagerComplaintTicket,useStartComplaintAssignmentTicket}from'@features/complaints'
import { ExecPageHeader } from '@components/executive/ExecPageHeader'
import { useCanCall } from '@features/permissions/my-permissions'
import { parentSectorLabel } from '@sdk/sectors.sdk'

type Picked={id:string;file:File;url:string;source:'camera'|'gallery'}
export default function ComplaintTicketPage(){
 const{complaintId=''}=useParams();const navigate=useNavigate();const{data:ticketItems=[],isLoading,isError,refetch}=useManagerComplaintTicket(complaintId);const items=useMemo(()=>[...ticketItems].sort((a,b)=>a.sequenceNo-b.sequenceNo),[ticketItems]);const{data:media=[]}=useComplaintItemsMedia(items.map(item=>item.id));const start=useStartComplaintAssignmentTicket();const complete=useCompleteComplaintAssignmentTicket();const canStartTicket=useCanCall('complaint_start_assignment_ticket');const canCompleteTicket=useCanCall('complaint_complete_assignment_ticket');const activeItems=items.filter(item=>item.status==='in_progress');const canStart=items.some(item=>['assigned','returned'].includes(item.status));const[files,setFiles]=useState<Array<Picked|null>>([]);const[notes,setNotes]=useState('');const[cameraIndex,setCameraIndex]=useState<number|null>(null);const[dragged,setDragged]=useState<number|null>(null);const[message,setMessage]=useState('');const urls=useRef<string[]>([])
 useEffect(()=>{setFiles(old=>Array.from({length:activeItems.length},(_,index)=>old[index]??null))},[activeItems.length])
 useEffect(()=>()=>urls.current.forEach(url=>URL.revokeObjectURL(url)),[])
 useEffect(()=>{const warn=(event:BeforeUnloadEvent)=>{if(!files.some(Boolean))return;event.preventDefault()};window.addEventListener('beforeunload',warn);return()=>window.removeEventListener('beforeunload',warn)},[files])
 const valid=(file:File)=>['image/jpeg','image/png','image/webp'].includes(file.type)&&file.size>0&&file.size<=25*1024*1024
 const picked=(file:File,source:Picked['source']):Picked=>{const value={id:crypto.randomUUID(),file,url:URL.createObjectURL(file),source};urls.current.push(value.url);return value}
 const replace=(index:number,file:File,source:Picked['source'])=>{if(!valid(file)){setMessage('الملف غير صالح؛ استخدم JPG أو PNG أو WebP وبحد أقصى 25MB.');return}setFiles(old=>{const next=[...old];const previous=next[index];if(previous)URL.revokeObjectURL(previous.url);next[index]=picked(file,source);return next});setMessage('')}
 const bulk=(incoming:File[])=>{const accepted=incoming.filter(valid);if(accepted.length!==activeItems.length){setMessage(`اختر ${activeItems.length} صورة بالضبط؛ صورة معالجة واحدة لكل صورة تلكؤ.`);return}setFiles(old=>{old.forEach(value=>value&&URL.revokeObjectURL(value.url));return accepted.map(file=>picked(file,'gallery'))});setMessage('تم توزيع الصور حسب ترتيبها. راجع الأزواج واسحب صور المعالجة لتصحيح المطابقة.')}
 const remove=(index:number)=>setFiles(old=>{const next=[...old];const value=next[index];if(value)URL.revokeObjectURL(value.url);next[index]=null;return next})
 const move=(from:number,to:number)=>{if(from===to||to<0||to>=files.length)return;setFiles(old=>{const next=[...old];[next[from],next[to]]=[next[to]??null,next[from]??null];return next})}
 const submit=()=>{if(files.length!==activeItems.length||files.some(value=>!value)){setMessage('أكمل صورة المعالجة المقابلة لكل تلكؤ قبل الإرسال.');return}complete.mutate({complaintId,files:activeItems.map((item,index)=>({itemId:item.id,file:files[index]!.file,source:files[index]!.source})),notes},{onSuccess:count=>{setMessage(`تم إرسال ${count} معالجة للتدقيق بنجاح.`);window.setTimeout(()=>navigate('/manager/complaints'),700)},onError:error=>setMessage(error instanceof Error?error.message:'تعذر إرسال التذكرة للتدقيق.')})}
 if(isLoading)return <div className="h-64 animate-pulse rounded-3xl bg-slate-100"/>;if(isError)return <section className="rounded-3xl border border-red-200 bg-red-50 p-10 text-center"><h2 className="font-black text-red-900">تعذر تحميل التذكرة</h2><p className="mt-2 text-sm text-red-700">تحقق من الاتصال ثم أعد المحاولة؛ لم تُعرض بيانات ناقصة.</p><button onClick={()=>void refetch()} className="mt-4 rounded-xl bg-red-800 px-4 py-2 font-bold text-white">إعادة المحاولة</button></section>;if(!items.length)return <section className="rounded-3xl border bg-white p-12 text-center"><h2 className="font-black">التذكرة غير موجودة أو غير مسندة إليك</h2><Link to="/manager/complaints" className="mt-4 inline-block text-blue-700">العودة للتذاكر</Link></section>
 const first=items[0]!;const completed=items.filter(item=>!['assigned','returned','in_progress'].includes(item.status)).length
 return <section className="space-y-6" dir="rtl"><ExecPageHeader icon="clipboard" title={first.ticketName} subtitle={<><span className="font-bold text-[#f3d06a]">{first.referenceNo}</span> · {new Date(first.receivedAt).toLocaleString('ar-IQ-u-nu-latn')} · {`بلدية ${parentSectorLabel(first.sector)}`} · {items.length} تلكؤ</>}
  stats={[{ label: 'أُرسل للتدقيق', value: `${completed}/${items.length}`, tone: 'gold' }]}
  actions={<Link to="/manager/complaints" className="inline-flex h-9 items-center gap-1 rounded-xl bg-white/10 px-3 text-xs font-black text-white ring-1 ring-white/25 hover:bg-white/20"><ArrowRight size={15}/>العودة إلى التذاكر</Link>} />
  {message&&<p role="status" className="rounded-2xl border border-blue-200 bg-blue-50 p-4 text-sm font-bold text-blue-900">{message}</p>}
  {files.some(Boolean)&&<p className="rounded-2xl border border-amber-200 bg-amber-50 p-3 text-xs font-bold text-amber-900">الصور المختارة محفوظة مؤقتاً على هذا الجهاز فقط؛ لا تغادر الصفحة قبل إرسال التذكرة للتدقيق.</p>}
  {canStart&&<article className="rounded-3xl border border-blue-200 bg-blue-50 p-6"><h2 className="text-lg font-black text-blue-950">ابدأ معالجة التذكرة كاملة</h2><p className="mt-2 text-sm leading-7 text-blue-800">ستبدأ جميع صور التلكؤ المسندة إليك من هذا البريد معاً. بيانات المركز والمحلة والزقاق للقراءة فقط.</p><button onClick={()=>start.mutate(complaintId,{onSuccess:count=>setMessage(`بدأت معالجة ${count} صورة تلكؤ.`),onError:error=>setMessage(error instanceof Error?error.message:'تعذر بدء التذكرة.')})} disabled={start.isPending||!canStartTicket.allowed} title={canStartTicket.title} className="mt-4 inline-flex items-center gap-2 rounded-2xl bg-blue-700 px-5 py-3 font-black text-white disabled:opacity-50"><Play size={18}/>{start.isPending?'جارٍ البدء…':'بدء معالجة التذكرة'}</button></article>}
  {activeItems.length>0&&<article className="rounded-3xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-lg font-black">صور المعالجة المطابقة</h2><p className="mt-1 text-sm text-slate-500">ارفع {activeItems.length} صورة مرة واحدة، أو أضف الصورة أمام كل تلكؤ. يمكنك تبديل مواضع صور المعالجة بالسحب.</p></div><label className="inline-flex cursor-pointer items-center gap-2 rounded-2xl bg-slate-900 px-5 py-3 font-bold text-white"><ImagePlus size={19}/>رفع {activeItems.length} صور دفعة واحدة<input type="file" multiple accept="image/jpeg,image/png,image/webp" className="sr-only" onChange={event=>{bulk(Array.from(event.target.files??[]));event.currentTarget.value=''}}/></label></div>
   <div className="mt-5 space-y-4">{activeItems.map((item,index)=>{const before=media.find(value=>value.itemId===item.id&&value.kind==='before');const after=files[index];return <section key={item.id} className="grid items-stretch gap-3 rounded-3xl border border-slate-200 bg-slate-50/60 p-3 lg:grid-cols-[1fr_64px_1fr]"><div className="overflow-hidden rounded-2xl border bg-white p-3"><div className="mb-2 flex flex-wrap items-center justify-between gap-2"><b>التلكؤ {index+1}</b><span className="flex items-center gap-1 rounded-lg bg-slate-100 px-2 py-1 text-xs"><Tag size={13}/>{item.title||'نوع غير محدد'}</span></div>{before?<a href={before.url} target="_blank" rel="noreferrer"><img src={before.url} alt={`صورة التلكؤ ${index+1}`} className="h-56 w-full rounded-xl bg-slate-100 object-contain"/></a>:<div className="flex h-56 items-center justify-center rounded-xl bg-slate-100 text-sm text-slate-500">الصورة غير متاحة</div>}<dl className="mt-3 grid grid-cols-2 gap-2 text-xs"><div className="rounded-lg bg-slate-50 p-2"><dt className="text-slate-500">المحلة</dt><dd className="font-black">{item.neighborhood||'—'}</dd></div><div className="rounded-lg bg-slate-50 p-2"><dt className="text-slate-500">الزقاق</dt><dd className="font-black">{item.alley||'—'}</dd></div></dl></div><div className="hidden items-center justify-center lg:flex"><ArrowRight className="rotate-180 text-blue-500" size={30}/></div><div draggable={Boolean(after)} onDragStart={()=>setDragged(index)} onDragOver={event=>event.preventDefault()} onDrop={()=>{if(dragged!==null)move(dragged,index);setDragged(null)}} className={`rounded-2xl border-2 border-dashed p-3 transition ${after?'border-emerald-300 bg-emerald-50':'border-blue-200 bg-white'}`}><div className="mb-2 flex items-center justify-between"><b className="text-emerald-900">المعالجة المقابلة {index+1}</b>{after&&<GripVertical className="cursor-grab text-slate-500"/>}</div>{after?<><img src={after.url} alt={`صورة المعالجة ${index+1}`} className="h-56 w-full rounded-xl bg-white object-contain"/><div className="mt-3 flex items-center justify-between gap-2"><span className="truncate text-xs text-slate-600">{after.file.name}</span><div className="flex flex-wrap gap-1"><button disabled={index===0} onClick={()=>move(index,index-1)} aria-label={`نقل صورة المعالجة ${index+1} إلى الموقع السابق`} className="rounded-lg border bg-white p-2 text-slate-700 disabled:opacity-30"><ArrowUp size={16}/></button><button disabled={index===files.length-1} onClick={()=>move(index,index+1)} aria-label={`نقل صورة المعالجة ${index+1} إلى الموقع التالي`} className="rounded-lg border bg-white p-2 text-slate-700 disabled:opacity-30"><ArrowDown size={16}/></button><button onClick={()=>setCameraIndex(index)} aria-label="استبدال بالكاميرا" className="rounded-lg border bg-white p-2 text-blue-700"><Camera size={16}/></button><label className="cursor-pointer rounded-lg border bg-white p-2 text-blue-700" aria-label="استبدال من الجهاز"><RotateCcw size={16}/><input type="file" accept="image/jpeg,image/png,image/webp" className="sr-only" onChange={event=>{const file=event.target.files?.[0];if(file)replace(index,file,'gallery');event.currentTarget.value=''}}/></label><button onClick={()=>remove(index)} aria-label="حذف صورة المعالجة" className="rounded-lg border bg-white p-2 text-red-700"><Trash2 size={16}/></button></div></div></>:<div className="flex h-56 flex-col items-center justify-center gap-3 rounded-xl bg-slate-50"><p className="text-sm font-bold text-slate-600">أضف صورة معالجة لهذا التلكؤ</p><div className="flex flex-wrap justify-center gap-2"><button onClick={()=>setCameraIndex(index)} className="inline-flex items-center gap-2 rounded-xl bg-blue-700 px-4 py-2 font-bold text-white"><Camera size={17}/>الكاميرا</button><label className="inline-flex cursor-pointer items-center gap-2 rounded-xl border bg-white px-4 py-2 font-bold text-blue-700"><ImagePlus size={17}/>من الجهاز<input type="file" accept="image/jpeg,image/png,image/webp" className="sr-only" onChange={event=>{const file=event.target.files?.[0];if(file)replace(index,file,'gallery');event.currentTarget.value=''}}/></label></div></div>}</div></section>})}</div>
   <label className="mt-5 block text-sm font-bold text-slate-700">ملاحظة عامة على معالجة التذكرة<textarea value={notes} onChange={event=>setNotes(event.target.value)} className="mt-2 min-h-24 w-full rounded-2xl border p-3" placeholder="اختياري: اكتب ملخص الأعمال المنفذة"/></label><div className={`mt-4 flex flex-wrap items-center justify-between gap-3 rounded-2xl border p-4 ${files.every(Boolean)&&files.length===activeItems.length?'border-emerald-200 bg-emerald-50':'border-amber-200 bg-amber-50'}`}><div><b className="text-sm">جاهزية الإرسال: {files.filter(Boolean).length} من {activeItems.length}</b><p className="mt-1 text-xs text-slate-600">{files.every(Boolean)&&files.length===activeItems.length?'اكتملت المطابقة. راجع الصور ثم أرسل التذكرة كاملة.':'أضف صورة معالجة أمام كل صورة تلكؤ لتفعيل الإرسال.'}</p></div><CheckCircle2 className={files.every(Boolean)&&files.length===activeItems.length?'text-emerald-600':'text-amber-500'}/></div><button onClick={submit} disabled={complete.isPending||files.some(value=>!value)||files.length!==activeItems.length||!canCompleteTicket.allowed} title={canCompleteTicket.title} className="mt-3 flex w-full items-center justify-center gap-2 rounded-2xl bg-emerald-700 px-5 py-4 text-lg font-black text-white shadow-sm disabled:cursor-not-allowed disabled:bg-slate-300 disabled:text-slate-600"><Send size={20}/>{complete.isPending?'جارٍ رفع التذكرة…':`إرسال ${activeItems.length} معالجة للتدقيق`}</button></article>}
  {!canStart&&!activeItems.length&&<div className="rounded-3xl border bg-white p-10 text-center"><CheckCircle2 className="mx-auto text-emerald-600" size={42}/><h2 className="mt-3 text-lg font-black">تم إرسال جميع صور هذه التذكرة للتدقيق</h2></div>}
  <CameraCapture open={cameraIndex!==null} onClose={()=>setCameraIndex(null)} onCapture={file=>{if(cameraIndex!==null)replace(cameraIndex,file,'camera')}}/>
 </section>
}
